// Types for the bundled copy of src/lib/reminders.ts (generated by `npm run build:api`).
export interface ReminderMessage { title: string; body: string; url: string; kind: 'training_day' | 'no_workout' }
export function decideReminder(profile: unknown, workouts: unknown[], programs: unknown[], now: Date): ReminderMessage | null;
export function isDue(profile: unknown, now: Date): boolean;
export const HISTORY_DAYS: number;
export function localNow(now: Date, timeZone: string): { date: string; minutes: number; weekday: number };
